package com.plantgrowth.forecasting.entity;
import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="users") public class User {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="full_name") private String fullName; @Column(unique=true) private String email; @Column(name="password_hash") private String passwordHash; @Enumerated(EnumType.STRING) private Role role=Role.USER; private boolean active=true; @Column(name="created_at") private Instant createdAt=Instant.now(); @Column(name="updated_at") private Instant updatedAt=Instant.now(); public Long getId(){return id;} public String getFullName(){return fullName;} public void setFullName(String x){fullName=x;} public String getEmail(){return email;} public void setEmail(String x){email=x.toLowerCase();} public String getPasswordHash(){return passwordHash;} public void setPasswordHash(String x){passwordHash=x;} public Role getRole(){return role;} public boolean isActive(){return active;}}
